// AUTO-GENERATED: extra air-fryer methods for FODMAP and family recipes,
// merged into the AIRFRYER map (defined in data.js). Loaded after data.js.
if (typeof AIRFRYER !== "undefined") Object.assign(AIRFRYER, {"fam-c-chicken-meatballs-with-piccata-sauce":["Roll the breadcrumb-coated chicken meatballs in a little olive oil and air fry at 380°F (190°C) for 10–12 min, shaking the basket halfway, until golden and 165°F (74°C) inside.","Make the lemon-caper piccata sauce on the stovetop, then toss the air-fried meatballs in it to finish."],"fam-c-roasted-mushrooms-in-garlic-butter":["Toss the whole mushrooms with the melted garlic butter, olive oil, Italian seasoning, salt and pepper, then air fry at 400°F (200°C) for 12–15 min, shaking once or twice, until tender and browned.","Sprinkle with the fresh parsley and serve hot."],"fam-c-best-blackened-salmon-recipe---ready-in":["Rub the salmon filets with vegetable oil and coat both sides with the blackening seasoning, then air fry at 400°F (200°C) for 7–9 min, until a dark crust forms and the salmon reaches 145°F (63°C).","Let rest a few minutes before serving."],"fam-c-avocado-chicken-enchiladas":["Assemble the rolled enchiladas in an air-fryer-safe dish, top with the salsa verde sauce and Mexican cheese, and air fry at 350°F (175°C) for 10–14 min, until heated through and the cheese is bubbling and lightly browned.","Top with fresh avocado and cilantro after cooking."],"fam-c-salisbury-steak":["Shape the beef mixture into oval patties and air fry at 380°F (190°C) for 10–12 min, flipping halfway, until browned and 160°F (70°C) inside.","Make the French onion gravy separately on the stovetop and spoon it over the air-fried patties."],"fam-c-easy-creamy-shrimp-enchiladas":["Toss the peeled shrimp with a little oil, salt and cumin and air fry at 400°F (200°C) for 5–7 min, shaking once, until pink and opaque (145°F / 63°C); saute the onion, pepper and jalapeno separately.","Fill and roll the tortillas, place in an air-fryer-safe dish, top with the cheese sauce, and air fry at 350°F (175°C) for 8–10 min, until bubbling."],"fam-c-grilled-grouper-with-watermelon-salsa":["Drizzle the grouper filets with olive oil and season with salt and pepper, then air fry at 400°F (200°C) for 7–9 min, until the fish flakes and reaches 145°F (63°C).","Serve topped with the fresh watermelon salsa."],"fam-c-blackened-fish-tacos-with-avocado-cilant":["Coat the tilapia filets in oil and the blackening spice blend, then air fry at 400°F (200°C) for 7–9 min, until blackened and the fish flakes at 145°F (63°C).","Flake into pieces and serve in tortillas with the slaw and avocado-cilantro sauce."],"fam-c-cheesy-chicken-spaghetti":["Combine the cooked spaghetti, cheese sauce, tomatoes, green chiles and shredded chicken in an air-fryer-safe dish and top with the remaining cheddar.","Air fry at 350°F (175°C) for 12–15 min, until hot, bubbly and lightly browned on top."],"fam-c-cheddar-bacon-egg-salad":["Air fry the bacon slices at 375°F (190°C) for 8–10 min, until crisp, then drain and crumble; hard-cook and chop the eggs separately.","Fold the crumbled bacon and cheddar into the egg salad and assemble the sandwiches."],"fam-c-easy-microwave-chicken-enchiladas":["Fill and roll the tortillas, arrange seam-side down in an air-fryer-safe dish, top with the remaining enchilada sauce and cheese, and air fry at 350°F (175°C) for 10–12 min, until the cheese is melted and bubbling.","Garnish with cilantro and serve with sour cream."],"fam-c-brown-sugar-meatloaf---with-a-secret-ing":["Press the beef mixture into an air-fryer-safe loaf pan, brush with half the brown sugar sauce, and air fry at 350°F (175°C) for 30–40 min, until 160–165°F (71–74°C) inside.","Brush with the remaining sauce in the last 5 min, then rest 5 min before slicing."],"fam-c-slow-cooker-creamy-ranch-chicken":["Air fry the seasoned chicken breasts at 375°F (190°C) for 12–16 min, flipping halfway, until 165°F (74°C) inside; air fry the bacon separately at 375°F (190°C) for 8–10 min until crisp.","Make the creamy ranch sauce on the stovetop, slice the chicken, and serve over rice topped with the crumbled bacon and green onions."],"fam-c-bacon-macaroni-salad":["Air fry the bacon strips at 375°F (190°C) for 8–10 min, until crisp, then drain and crumble.","Stir the crumbled bacon into the chilled macaroni salad just before serving so it stays crunchy."],"fam-c-best-green-bean-casserole":["Air fry the buttermilk-soaked, flour/panko-coated onions at 375°F (190°C) for 8–10 min, shaking often, until deep golden; blanch the green beans and make the mushroom cream sauce separately.","Combine the beans and sauce in an air-fryer-safe dish, air fry at 350°F (175°C) for 10–15 min until bubbling, then top with the crispy onions."],"fam-c-loaded-cauliflower":["Cut the cauliflower into florets, toss with a little oil, and air fry at 380°F (190°C) for 12–15 min, shaking once, until tender and lightly charred.","Mash and mix with the sour cream, cheddar, ranch mix, onion and garlic powder in an air-fryer-safe dish, top with butter, and air fry at 350°F (175°C) for 8–10 min until bubbling."],"fam-c-white-chicken-enchilada-pasta":["Season the 1-inch chicken pieces with creole seasoning and air fry at 400°F (200°C) for 8–10 min, shaking once, until 165°F (74°C).","Make the green chile cream sauce and pasta on the stovetop, then stir in the air-fried chicken to finish."],"fam-c-beef-rice-stuffed-cabbage-rolls":["Fill the blanched cabbage leaves with the beef-and-rice mixture, roll up, and place seam-side down in an air-fryer-safe dish; spoon the tomato sauce over the top.","Air fry at 350°F (175°C) for 18–22 min, until the beef reaches 160°F (71°C) and the cabbage is tender."],"fam-c-mediterranean-style-garlic-shrimp":["Toss the shrimp with the flour, smoked paprika, salt, pepper, coriander, cayenne and sugar and air fry at 400°F (200°C) for 5–7 min, shaking once, until pink and opaque (145°F / 63°C).","Make the shallot-garlic-tomato sauce on the stovetop and toss the air-fried shrimp in it with the lemon juice and parsley."],"fam-c-ratatouille":["Toss the cubed eggplant, zucchini, squash and bell peppers with olive oil, salt and pepper and air fry in batches at 400°F (200°C) for 12–15 min, shaking once or twice, until golden and tender.","Combine with the simmered tomato-onion-garlic-herb base and stir in the basil and parsley before serving."],"fam-c-slow-cooker-smothered-pork-chops":["Pat the pork chops dry, season with salt and pepper, and air fry at 375°F (190°C) for 10–14 min, flipping halfway, until 145°F (63°C) inside; air fry the bacon separately at 375°F (190°C) for 6–8 min.","Make the onion gravy on the stovetop, then spoon it over the air-fried chops."],"fam-c-eggplant-fries":["Dredge the eggplant batons in flour, egg, then the seasoned breadcrumbs, and mist with olive oil.","Air fry at 400°F (200°C) for 10–12 min, shaking halfway, until golden and crisp; serve with tzatziki or marinara."],"fam-c-bacon-wrapped-jalapeno-poppers":["Fill the jalapeno halves with the cream cheese and cheddar mixture and wrap each with a slice of bacon.","Air fry at 375°F (190°C) for 12–16 min, until the bacon is crispy and the peppers are tender."],"fam-c-sauteed-mushrooms-in-garlic-butter":["Toss the sliced mushrooms with the melted butter, salt and pepper and air fry at 400°F (200°C) for 8–10 min, shaking once or twice, until caramelized.","Toss with the minced garlic and air fry 1–2 min more, then sprinkle with parsley."],"fam-c-mediterranean-grain-bowls-recipe-with-le":["Toss the zucchini rounds with olive oil and salt and air fry at 400°F (200°C) for 8–10 min, shaking once, until tender and lightly browned.","Assemble the bowls with the farro, lentils, chickpeas, tomatoes, avocado and air-fried zucchini, then drizzle with the lemon-za'atar dressing."],"fam-c-crock-pot-chicken-and-stuffing":["Season the chicken breasts with Italian seasoning, salt, and pepper and lightly oil. Air fry at 375°F (190°C) for 16-20 min, flipping halfway, until 165°F (74°C); slice or shred.","Prepare the stuffing, cream of chicken soup, sour cream, and green beans separately on the stovetop, then combine with the air-fried chicken."],"fam-c-chicken-scampi":["Toss the diced chicken with flour, Italian seasoning, salt, and pepper and a little oil. Air fry at 400°F (200°C) for 8-10 min, shaking once, until 165°F (74°C).","Cook the spaghetti and make the garlic-butter-wine sauce separately on the stovetop, then toss with the air-fried chicken, parsley, and parmesan."],"fam-c-salmon-recipe-with-garlic-lemon-butter-s":["Pat the salmon fillets dry, brush with olive oil, and season with salt and pepper. Air fry at 400°F (200°C) for 7-9 min, until 145°F (63°C).","Make the garlic lemon butter sauce separately in a saucepan and drizzle over the air-fried salmon; garnish with parsley and lemon."],"fam-c-jambalaya":["Air fry the sliced andouille sausage at 380°F (190°C) for 6-8 min, shaking once, until browned and crisp.","Toss the peeled shrimp with a little oil and air fry at 400°F (200°C) for 5-7 min, shaking once, until pink and 120°F (49°C).","Cook the rice, vegetables, tomatoes, and seasonings separately on the stovetop, then fold in the air-fried sausage and shrimp with the chicken, green onions, and parsley."],"fam-c-mediterranean-chicken-tray-bake-recipe":["Toss the red peppers and onion wedges with olive oil and air fry at 400°F (200°C) for 8 min, shaking once.","Stuff the soft cheese under the chicken skin, brush with oil, season, and add to the basket with the cherry tomatoes and olives. Cook at 380°F (190°C) for 18-22 min, until the chicken is 165°F (74°C) and golden."],"fam-c-garlic-parmesan-shrimp-scampi-pasta":["Toss the peeled shrimp with olive oil, cajun seasoning, garlic, and red pepper flakes. Air fry at 400°F (200°C) for 5-7 min, shaking once, until pink and 120°F (49°C).","Cook the linguine and make the lemon-butter-wine sauce separately, then toss with the air-fried shrimp, parmesan, and parsley."],"fam-c-creole-jambalaya":["Toss the peeled shrimp with a little oil and air fry at 400°F (200°C) for 5-7 min, shaking once, until pink and 120°F (49°C).","Cook the ham, rice, tomatoes, broth, and seasonings separately on the stovetop, then stir in the air-fried shrimp and parsley."],"fam-c-skewered-grilled-potatoes":["Thread the quartered red potatoes onto soaked skewers and brush with the mayonnaise-wine-rosemary-garlic marinade.","Air fry the skewers at 400°F (200°C) for 16-20 min, turning and brushing with marinade halfway, until fork-tender and golden."],"fam-c-greek-potatoes":["Toss the Yukon Gold potato wedges with olive oil, lemon juice, salt, and dried oregano. Air fry at 400°F (200°C) for 20-25 min, shaking 2-3 times, until tender and golden brown.","Toss the hot potatoes with fresh oregano and top with crumbled feta before serving."],"fam-c-king-ranch-chicken-casserole-no-canned-s":["Build the chicken, vegetable, and cheese layers with tortilla chips in an air-fryer-safe dish per the recipe.","Air fry covered with foil at 350°F (175°C) for 20 min, then uncover and cook 8-12 min more until bubbly and lightly browned. Let stand 10 min before serving."],"fam-c-greek-rice-stuffed-peppers":["Air fry the hollowed bell peppers (tops on) at 350°F (175°C) for 12-15 min to soften.","Fill the peppers with the sauteed rice, carrot, zucchini, tomato paste, and herb mixture, replace the tops, and air fry at 350°F (175°C) for 12-15 min more until the peppers are soft."],"fam-c-the-best-sour-cream-chicken-enchiladas":["Roll the chicken-onion-rotel filling in tortillas and place seam-side down in an air-fryer-safe dish; pour over the sour cream sauce and top with cheese.","Air fry at 350°F (175°C) for 12-16 min until heated through and the cheese is melted and bubbly."],"fam-c-smothered-skillet-beef-burritos":["Roll the beef, refried beans, rice, and cheese into the tortillas and place seam-side down in an air-fryer-safe dish.","Air fry at 350°F (175°C) for 10-12 min until crisp, then drizzle with enchilada sauce, top with remaining cheese, and cook 4-5 min more until melted and 165°F (74°C)."],"fam-c-skillet-creamy-garlic-chicken-with-brocc":["Season the chicken breasts with salt, pepper, and paprika and brush with oil. Air fry at 380°F (190°C) for 16-20 min, flipping halfway, until 165°F (74°C).","Air fry the chopped broccoli (oiled) at 380°F (190°C) for 6-8 min, shaking once, then make the creamy garlic sauce separately and combine."],"fam-c-mexican-chicken-spaghetti":["Combine the cooked angel hair, chicken, soups, Rotel, and sour cream and transfer to an air-fryer-safe dish.","Air fry covered with foil at 350°F (175°C) for 18-22 min until hot and bubbly, then top with cheese and cook 2-3 min more until melted."],"fam-c-creamy-shrimp-and-roasted-red-pepper-lin":["Season the peeled shrimp with salt and pepper and toss with a little olive oil. Air fry at 400°F (200°C) for 5-7 min, shaking once, until pink and 120°F (49°C).","Cook the linguine and make the roasted red pepper cream sauce with spinach separately, then fold in the air-fried shrimp."],"fam-c-zaatar-garlic-salmon":["Toss the baby potatoes, grape tomatoes, and broccoli with olive oil, garlic, za'atar, coriander, salt, and pepper. Air fry at 400°F (200°C) for 12-15 min, shaking once.","Add the seasoned, garlic-and-za'atar-topped salmon fillets to the basket and cook at 400°F (200°C) for 7-9 min, until 145°F (63°C); finish with lemon juice."],"fam-c-creamy-lemon-parmesan-chicken-piccata":["Dredge the halved chicken breasts in the flour-parmesan mixture and spray with oil. Air fry at 380°F (190°C) for 12-16 min, flipping halfway, until golden and 165°F (74°C).","Make the creamy lemon-caper-parmesan sauce separately in a skillet, then spoon over the air-fried chicken and garnish with parsley and capers."],"fam-c-cajun-shrimp-and-dirty-rice-skillet":["Toss the deveined shrimp with oil and 1 tbsp Cajun seasoning, then air fry at 400°F (200°C) for 6–8 min, shaking once, until pink and 120°F (49°C).","Air fry the sliced sausage at 380°F (193°C) for 8–10 min, shaking once, until browned; cook the rice and vegetable base on the stovetop and combine."],"fam-c-mongolian-beef-ramen-noodles---jo-cooks":["Toss the cornstarch-coated flank steak strips with a little oil and air fry at 400°F (200°C) for 8–10 min, shaking twice, until browned and crisp.","Air fry the bell pepper strips at 400°F (200°C) for 5–6 min, then toss the beef and peppers with the cooked sauce and ramen noodles."],"fam-c-chicken-broccoli-and-rice-casserole":["Assemble the rice, sour cream sauce, chicken, broccoli and Velveeta in a greased air-fryer-safe dish and top with the french-fried onions.","Air fry at 350°F (175°C) for 12–18 min, until heated through and bubbling and the onions are golden."],"fam-c-tortellini-carbonara":["Air fry the chopped bacon at 350°F (175°C) for 7–10 min, shaking once, until crisp; drain on paper towels.","Cook the tortellini and combine with the cream, Parmesan, parsley and air-fried bacon on the stovetop, then serve."],"fam-c-white-chicken-enchilada-pasta-2":["Toss the 1-inch chicken pieces with oil and creole seasoning, then air fry at 400°F (200°C) for 8–10 min, shaking once, until 165°F (74°C).","Build the green chili sour cream sauce and angel hair pasta on the stovetop, then fold in the air-fried chicken and Jack cheese."],"fam-c-baked-macaroni-and-cheese":["Cook the macaroni and stir into the cheddar-Swiss béchamel, then transfer to a greased air-fryer-safe dish.","Air fry at 350°F (175°C) for 10–15 min, until browned and bubbly on top."],"fam-c-grandmas-chicken-casserole":["Layer the chicken, cream of chicken soup and cheddar in a greased air-fryer-safe dish, then top with the butter-coated panko.","Air fry at 350°F (175°C) for 15–20 min, until heated through and the crumbs are golden brown; rest 10 min."],"fam-c-rib-eye-steak":["Season the rib-eye steaks all over with the rub, salt and pepper, then air fry at 400°F (200°C) for 10–14 min, flipping halfway, until 130°F (54°C) for medium-rare.","Rest the steaks 5–10 min before serving."],"fam-c-chicken-au-poivre":["Season the chicken thighs with salt and a little oil, then air fry at 380°F (193°C) for 14–18 min, flipping once, until 165°F (74°C).","Make the shallot, broth, cream and cracked-peppercorn sauce on the stovetop and spoon over the air-fried chicken."],"fam-c-baked-to-perfection-salmon-foil-packet-w":["Saute the onion, garlic and mushrooms with thyme, parsley and broth on the stovetop until softened.","Place the salmon fillets in foil packets (or oiled, in a dish) topped with the mushroom mixture and air fry at 400°F (200°C) for 9–12 min, until 145°F (63°C)."],"fam-c-cheesy-chicken-and-wild-rice-casserole":["Combine the cooked wild rice, chicken, soup, broth and seasonings with the cheese in a greased air-fryer-safe dish and top with the buttered stuffing.","Air fry at 350°F (175°C) for 15–20 min, until bubbling and the stuffing is golden brown; rest 5 min."],"fam-c-high-protein-pasta":["Toss the bite-sized chicken with oil, Cajun and Italian seasoning, then air fry at 400°F (200°C) for 8–10 min, shaking once, until 165°F (74°C).","Cook the pasta and blend the cottage cheese sauce, then combine with the air-fried chicken, sun-dried tomatoes, spinach and basil."],"fam-c-favorite-chicken-potpie":["Fill a pie crust-lined air-fryer-safe dish with the chicken, peas, corn and potato-carrot filling in the thickened sauce, top with crust and cut slits.","Air fry at 360°F (182°C) for 20–30 min, until the crust is golden brown; rest 15 min before cutting."],"fam-c-skillet-chicken-in-creamy-sun-dried-toma":["Season the chicken with salt, pepper and a little oil, then air fry at 380°F (193°C) for 14–18 min, flipping once, until 165°F (74°C).","Make the sun-dried tomato cream sauce on the stovetop and spoon over the air-fried chicken with parmesan and basil."],"fam-c-this-giant-bbq-sandwich-is-everything-yo":["Rub the baby back ribs with the spice mix and air fry at 350°F (175°C) for 30–40 min, flipping once, until tender.","Brush with the barbecue-honey glaze and air fry 5–7 min more at 400°F (200°C), until bubbling and caramelized; build the sandwich with caramelized onions and toasted bread."],"fam-c-shrimp-scampi-pasta-with-asparagus":["Toss the asparagus pieces with oil, salt and pepper and air fry at 400°F (200°C) for 6–8 min, shaking once, until crisp-tender.","Toss the shrimp with oil, garlic and red pepper flakes and air fry at 400°F (200°C) for 5–7 min, until pink; toss with the cooked pasta, lemon and parsley."],"fam-c-cheddar-and-chive-mashed-potatoes":["Boil and mash the potatoes, then beat in the cream cheese, cheddar, sour cream, onion, egg, salt and pepper and transfer to a greased air-fryer-safe dish.","Air fry at 350°F (175°C) for 18–25 min, until heated through; top with extra cheddar and air fry 2–3 min more until melted."],"fam-c-spanish-chicken-and-rice":["Season the chicken pieces with taco seasoning, salt, pepper and a little oil, then air fry at 400°F (200°C) for 8–10 min, shaking once, until 165°F (74°C).","Cook the Spanish rice with salsa, corn and black beans on the stovetop, then stir in the air-fried chicken, cheese, lime and cilantro."],"fam-c-beef-and-mushrooms-with-smashed-potatoes":["Air fry the 1½-inch red potato pieces (oiled, salted) at 400°F (200°C) for 18–22 min, shaking once, until fork-tender, then smash with butter and cream.","Cook and crumble the beef with mushrooms and onion into the broth gravy on the stovetop and spoon over the smashed potatoes; top with fried onions."],"fam-c-million-dollar-spaghetti":["Brown the ground beef with onion and garlic and combine with sauce, the cream cheese mixture and cooked spaghetti, then layer with cheeses in an air-fryer-safe dish.","Air fry at 350°F (175°C) for 15–20 min, until the cheese is fully melted and bubbly."],"fam-c-slow-cooked-tri-tips-gravy-with-mashed-p":["Season the tri-tip pieces with salt and pepper, lightly oil, and air fry at 400°F (200°C) for 14–20 min, flipping once, until 130°F (54°C) for medium-rare; rest before slicing.","Make the consommé-thyme gravy with the butter-flour paste on the stovetop and serve the sliced tri-tip with gravy over mashed potatoes."],"fam-c-southwest-crock-pot-chicken-and-rice":["Season the chicken breasts with taco seasoning, paprika and pepper, lightly oil, and air fry at 380°F (193°C) for 16–20 min, flipping once, until 165°F (74°C), then shred.","Combine with the beans, corn, tomatoes, soup, milk, cooked rice and cheddar on the stovetop and heat until the cheese melts."],"fam-c-easy-one-pan-ratatouille":["Toss the sliced eggplant, zucchini and bell peppers with olive oil, salt and pepper and air fry at 375°F (190°C) for 12–16 min, shaking once, until tender and lightly browned.","Make the tomato-basil sauce on the stovetop and spoon the air-fried vegetables over it; serve over pasta or on its own."],"fam-c-chicken-chow-mein":["Toss the marinated thin-sliced chicken with a little oil and air fry at 400°F (200°C) for 8–10 min, shaking once, until 165°F (74°C).","Stir-fry the cabbage and carrot with the sauce and noodles on the stovetop, then toss in the air-fried chicken and green onions."],"fam-c-greek-salad-penne":["Toss the drained chickpeas and bell pepper strips with olive oil, garlic, red pepper flakes and salt and air fry at 400°F (200°C) for 10–12 min, shaking once, until the chickpeas are crisp and the pepper is tender.","Toss with the cooked penne, olives, arugula, oregano and feta and drizzle with olive oil."],"fam-c-one-pan-shrimp-and-rice-healthy-deliciou":["Pat the shrimp dry, toss with oil, salt, coriander, chile, cumin, paprika and turmeric, then air fry at 400°F (200°C) for 5–7 min, until pink and fully cooked.","Cook the spiced rice with onion, pepper, garlic and peas on the stovetop and fold in the air-fried shrimp with fresh parsley."],"fam-c-cheesy-ranch-potatoes-my-favorite-potato":["Toss the diced potatoes with melted butter, salt, pepper and seasoning and air fry at 400°F (200°C) for 18–22 min, shaking once or twice, until fork-tender and crisp.","Top with ranch dressing and shredded cheese and air fry 2–4 min more, until the cheese is melted."],"fam-c-creamy-shrimp-pasta":["Air fry the sliced mushrooms (lightly oiled) at 380°F (193°C) for 8–10 min, shaking once, until golden.","Toss the shrimp with oil, garlic, red pepper flakes, paprika and salt and air fry at 400°F (200°C) for 5–7 min, until pink; make the cream cheese sauce and combine with the linguine, mushrooms and shrimp."],"fam-c-stuffed-chicken-marsala":["Stuff the chicken breasts with mozzarella, sun-dried tomatoes and parmesan, secure with toothpicks, rub with oil, salt, pepper and Italian seasoning.","Air fry at 380°F (193°C) for 18–24 min, flipping once, until 165°F (74°C) and the cheese is melted; make the marsala-mushroom cream sauce on the stovetop and spoon over."],"fam-c-sausage-sawmill-gravy-biscuits":["Air fry the crumbled pork breakfast sausage at 375°F (190°C) for 7–9 min, shaking and breaking up once, until browned and 160°F (71°C).","Make the milk-and-flour sawmill gravy on the stovetop, stir in the cooked sausage, and serve over the warmed split biscuits."],"fam-c-chicken-and-sweet-potato-bowl-2":["Air fry the sweet potato half-moons (oiled, salted) at 400°F (200°C) for 16–20 min, shaking twice, until tender and caramelized.","Air fry the drained chickpeas (oiled) at 390°F (200°C) for 12–15 min, shaking often, until crisp; toss with za'atar, sumac, and shawarma seasoning.","Air fry the marinated chicken thigh strips at 380°F (193°C) for 10–12 min, flipping once, until 165°F (74°C); assemble the bowls with greens, farro, onions, pistachios, feta, and dressing."],"fam-c-spicy-fish-tacos-with-fresh-lime-sauce-r":["Air fry the taco-seasoned white fish fillets (lightly oiled) at 400°F (200°C) for 8–10 min, until the fish flakes easily and reaches 145°F (63°C), then break into chunks.","Make the lime-yogurt slaw and warm the taco shells separately, then fill with fish, slaw, and tomato."],"fam-c-slow-cooker-stuffed-peppers":["Brown the ground beef with onion on the stovetop and mix with the rice, tomato sauce, and 1 cup cheese, then stuff the trimmed bell peppers.","Air fry the stuffed peppers (in an air-fryer-safe dish) at 350°F (177°C) for 15–20 min, until the peppers are soft, topping with the remaining cheese in the last 3–4 min to melt."],"fam-c-baked-spaghetti-meatballs":["Air fry the meatballs at 380°F (193°C) for 9–12 min, shaking once, until browned and 160°F (71°C) (skip if already fully cooked, just reheat 4–5 min).","Cook the spaghetti and marinara on the stovetop, combine with the meatballs, top with cheese, and finish the assembled dish in an air-fryer-safe dish at 350°F (177°C) for 8–10 min until bubbly."],"fam-c-chicken-fajita-pasta":["Air fry the seasoned bite-sized chicken at 380°F (193°C) for 9–11 min, shaking once, until 165°F (74°C).","Air fry the diced onion and bell peppers (oiled) at 390°F (200°C) for 8–10 min, shaking once, until slightly charred; cook the pasta in the broth-cream-tomato sauce on the stovetop and combine."],"fam-c-blackened-shrimp-tacos":["Toss the shrimp with the blackening seasoning and a little oil, then air fry at 400°F (200°C) for 5–7 min, shaking once, until firm, pink, and opaque.","Make the slaw and smoky garlic-lime sauce, toast the tortillas, then fill with slaw, shrimp, sauce, and green onions."],"fam-c-mediterranean-baked-fish-recipe-with-tom":["Simmer the tomato-caper-raisin sauce on the stovetop; spoon half into an air-fryer-safe dish and lay the seasoned white fish fillets on top, covering with the rest of the sauce, lemon juice, and zest.","Air fry at 380°F (193°C) for 12–16 min, until the fish flakes easily and reaches 145°F (63°C); garnish with parsley or mint."],"fam-c-roasted-new-red-potatoes":["Toss the halved red new potatoes with olive oil, salt, and pepper, then air fry cut-side down at 400°F (200°C) for 18–22 min, shaking once, until tender and golden brown."],"fam-c-chicken-alfredo-baked-ziti":["Air fry oiled, seasoned chicken breasts at 380°F (193°C) for 10–14 min, flipping once, until 165°F (74°C), then shred or chop.","Toss the cooked ziti with the alfredo sauce and chicken, layer with mozzarella in an air-fryer-safe dish, and air fry at 350°F (177°C) for 8–12 min, until melted and golden."],"fam-c-country-captain-chicken":["Air fry the flour-dredged chicken pieces (lightly oiled) at 380°F (193°C) for 18–22 min, flipping once, until golden and 165°F (74°C).","Make the curried tomato-pepper-currant sauce on the stovetop, then nestle in the air-fried chicken to finish; serve over rice with toasted almonds."],"fam-c-gemista-greek-stuffed-vegetables":["Stuff the hollowed bell peppers and tomatoes with the rice-herb filling and replace their tops; oil the potato wedges.","Air fry the stuffed vegetables and potato wedges (in an air-fryer-safe dish, foil-covered) at 360°F (182°C) for 30 min, then uncover and air fry 12–18 min more, until the rice is cooked and the vegetables are soft and charred in spots."],"fam-c-how-to-cook-skirt-steak":["Pat the skirt steak dry, rub with olive oil, salt, and pepper, then air fry at 400°F (200°C) for 6–9 min, flipping once, until 130°F (54°C) for medium-rare.","Rest 10 min loosely tented with foil, then slice thinly across the grain."],"fam-c-chicken-spaghetti-with-red-sauce":["Air fry the marinated bite-sized chicken at 380°F (193°C) for 9–12 min, shaking once, until 165°F (74°C).","Make the tomato-basil red sauce on the stovetop, stir in the air-fried chicken, and serve over pasta with parmesan."],"fam-c-one-pot-creamy-pesto-chicken-pasta":["Air fry the 1-inch chicken breast pieces (lightly oiled) at 380°F (193°C) for 9–11 min, shaking once, until lightly browned and 165°F (74°C).","Cook the pasta in broth and milk on the stovetop, stir in cream cheese, pesto, and parmesan, then fold in the air-fried chicken, spinach, and sun-dried tomatoes."],"fam-c-greek-chicken-kebabs-with-tzatziki-sauce":["Thread the marinated chicken cubes with red bell pepper, zucchini, and red onion onto skewers (use shorter ones to fit the basket).","Air fry at 380°F (193°C) for 12–16 min, turning once, until the chicken reaches 165°F (74°C) and the vegetables are charred; serve with tzatziki."],"fam-c-slow-cooker-general-tsos-chicken":["Toss the cubed chicken in the cornstarch, mist with oil, and air fry at 400°F (200°C) for 12–15 min, shaking twice, until crisp and 165°F (74°C).","Simmer the hoisin-soy-garlic-ginger sauce on the stovetop until thickened, toss with the crispy chicken, and serve over rice with green onions and sesame seeds."],"fam-c-creamy-cajun-chicken-pasta":["Toss the chicken strips with the Cajun seasoning, then air fry at 380°F (193°C) for 8–10 min, shaking once, until 165°F (74°C).","Make the cream sauce with green onion, sun-dried tomatoes, and parmesan on the stovetop, toss with the linguine, and top with the air-fried chicken."],"fam-c-one-pot-chicken-and-rice":["Air fry the oiled, seasoned bone-in chicken thighs/drumsticks at 380°F (193°C) for 22–28 min, flipping once, until skin is crisp and the meat reaches 175°F (79°C).","Cook the rice with the sauteed peppers, celery, garlic, thyme, lemon, and stock on the stovetop, then nestle in the air-fried chicken to serve."],"fam-c-butter-chicken":["Air fry the marinated chicken thigh pieces at 400°F (200°C) for 10–12 min, shaking once, until lightly charred and 165°F (74°C).","Make the tomato-cream butter sauce on the stovetop, then stir in the air-fried chicken and simmer briefly; serve over basmati rice with cilantro."],"fam-c-easy-homemade-philly-cheesesteaks-recipe":["Air fry the sliced bell peppers and onion (oiled, salted) at 390°F (200°C) for 10–14 min, shaking once, until caramelized.","Add the thinly sliced sirloin steak and air fry at 400°F (200°C) for 5–7 min, tossing once, until cooked through; combine with the veggies, top with provolone to melt, and pile into the toasted hoagie rolls."],"fam-c-italian-style-chicken-peppers":["Saute the chopped green pepper and mix with the cream cheese; season the chicken breasts with salt and pepper and top with the pepper mixture.","Air fry the topped chicken (in an air-fryer-safe dish with the warmed pasta sauce and mozzarella) at 380°F (193°C) for 14–18 min, until the chicken reaches 165°F (74°C) and the cheese is melted."],"fam-c-kielbasa-veggie-sheet-pan-dinner":["Air fry the halved red potatoes and baby carrots (tossed with 2 Tbsp oil and half the herb mix) at 400°F (200°C) for 12–15 min, shaking once.","Add the kielbasa rounds, asparagus, and onion (tossed with remaining oil, garlic, and herbs) and cook 8–10 min more, shaking once, until veggies are roasted and sausage is browned."],"fam-c-garlicky-roasted-mushrooms":["Toss the mushrooms with olive oil, minced garlic, chives, salt, and pepper, then air fry at 400°F (200°C) for 8–12 min, shaking once or twice, until browned to your liking.","Dust with garlic powder and serve warm."],"fam-c-chicken-pot-pie-casserole":["Prepare the chicken-and-vegetable filling on the stovetop as written, then spoon it into an air-fryer-safe dish and top with the lattice crust brushed with egg wash.","Air fry at 350°F (175°C) for 18–25 min, until the crust is golden and the filling is bubbling; tent with foil if the top browns too fast."],"fam-c-honey-garlic-pork-tenderloin":["Rub the trimmed tenderloin with the brown sugar spice mix and a little oil, then air fry at 400°F (200°C) for 18–22 min, flipping halfway, until 145°F (63°C) internal.","Rest 10 min while you simmer the honey, soy sauce, vinegar, and garlic into a glaze; slice and serve with the sauce."],"fam-c-baked-gnocchi-casserole-in-creamy-tomato":["Make the creamy tomato sauce on the stovetop and toss with the cooked gnocchi, then transfer to an air-fryer-safe dish and top with mozzarella.","Air fry at 350°F (175°C) for 8–12 min, until the cheese is melted and golden; garnish with basil."],"fam-c-bacon-jalapeno-popper-twice-baked-potato":["Prick the potatoes, rub with butter and seasoned salt, and air fry at 400°F (200°C) for 35–40 min, until fork-tender.","Halve, scoop, and mix the flesh with cream cheese, jalapeño, bacon, half the cheddar, salt, and pepper; refill the skins, top with remaining cheddar.","Return to the air fryer at 375°F (190°C) for 6–9 min, until heated through and the cheese melts; garnish with reserved bacon."],"fam-c-creamy-spinach-artichoke-chicken":["Season the pounded chicken breasts with salt and pepper, oil lightly, and air fry at 375°F (190°C) for 12–16 min, flipping halfway, until 165°F (74°C) internal.","Meanwhile make the creamy spinach-artichoke sauce on the stovetop, then spoon it over the air-fried chicken to serve."],"fam-c-best-crispy-baja-fish-tacos-with-pico-de":["Coat the white fish strips in the cracker-panko batter, spritz with oil, and air fry at 400°F (200°C) for 8–11 min, flipping halfway, until golden and 145°F (63°C) internal.","Warm the tortillas separately and assemble with cabbage, pico de gallo, white sauce, and a squeeze of lime."],"fam-c-chicken-kabobs":["Thread the marinated chicken cubes, bell peppers, and red onion onto skewers (trimmed to fit the basket) and air fry at 400°F (200°C) for 12–15 min, turning halfway, until the chicken reaches 165°F (74°C).","Serve over warm pita drizzled with tahini sauce."],"fam-c-taco-lasagna---only-7-ingredients":["Brown the taco-seasoned ground beef on the stovetop, then layer the noodles, ricotta-egg mix, beef, salsa, and cheddar in an air-fryer-safe dish.","Cover with foil and air fry at 350°F (175°C) for 25–30 min, removing the foil for the last 5–7 min, until bubbly and the cheese is melted; rest 10 min before cutting."],"fam-c-spinach-artichoke-chicken-bake":["Brown the chicken pieces with onion, garlic, and basil, then combine with the pepper flakes, artichokes, tomatoes, and spinach in an air-fryer-safe dish and top with the breadcrumb-Parmesan mix.","Air fry at 350°F (175°C) for 12–16 min, until bubbly and the topping is browned (chicken at 165°F / 74°C); garnish with basil."],"fam-c-chicken-and-gruyere-turnovers":["Fill the puff pastry rectangles with the chicken, Gruyère, and peas, seal, and brush the tops with beaten egg.","Air fry at 360°F (180°C) for 12–16 min, until golden and puffed; serve with Dijon mustard."],"fam-c-mediterranean-chicken-with-roasted-veget":["Toss the sliced potatoes, courgette, onion, pepper, tomatoes, and olives with oil and spread in an air-fryer-safe dish; air fry at 390°F (200°C) for 12–15 min, shaking once.","Slash the chicken breasts, spread with the olive oil-pesto mix, lay on the veggies, and cook 12–15 min more, until the chicken reaches 165°F (74°C) and the veggies are tender."],"fam-swedish-meatballs":["Roll the seasoned beef-and-chicken mixture into 1½-inch balls and air fry at 400°F (200°C) for 10–13 min, shaking once, until no longer pink and 165°F (74°C) internal.","Meanwhile make the gravy on the stovetop, then add the air-fried meatballs to simmer until coated; garnish with parsley."],"fam-green-chile-chicken-enchiladas":["Fill and roll the tortillas with the chicken-bean-corn-cheese mixture, place seam-down in an air-fryer-safe dish over a layer of salsa verde, then top with remaining sauce and cheese.","Air fry at 350°F (175°C) for 12–16 min, until bubbly and the cheese is melted; garnish with cilantro."],"fam-cod-provencal":["Make the tomato-fennel-olive sauce on the stovetop and spread it in an air-fryer-safe dish, then nestle in the seasoned cod fillets and spoon a little sauce over top.","Air fry at 350°F (175°C) for 8–11 min, until the cod flakes easily and reaches 145°F (63°C); garnish with parsley."],"fam-grilled-salmon-avocado-salsa":["Rub the salmon fillets with olive oil and the chili-cumin-paprika spice mix, then air fry skin-side down at 400°F (200°C) for 7–10 min, until 145°F (63°C) internal.","Top with the chilled avocado-lime salsa and serve."],"fam-enchilada-stuffed-peppers":["Brown the taco-seasoned beef with onion, green chiles, and enchilada sauce on the stovetop, then stuff the hollowed bell peppers, layering with the Mexican cheese.","Air fry the stuffed peppers at 350°F (175°C) for 12–16 min, until the peppers are tender and the cheese is melted; serve with sour cream and cilantro."],"fam-sheet-pan-gnocchi":["Toss the gnocchi, bell peppers, red onion, cherry tomatoes, and garlic with olive oil and the herbs, then air fry at 400°F (200°C) for 15–20 min, shaking twice, until the gnocchi is crisp and the veggies are roasted.","Stir in the baby spinach and cook 2–3 min more until wilted; serve with shaved Parmesan."],"fam-air-fryer-greek-chicken":["Air fry the marinated chicken breasts at 400°F (200°C) for 7 min, then flip.","Add the marinated zucchini, red onion, and cherry tomatoes to the basket and cook 7–8 min more, until the chicken reaches 165°F (74°C) and the veggies are tender; garnish with crumbled feta."],"fam-chicken-lazone":["Rub the chicken breasts with salt and half the chili-paprika spice mix, oil lightly, and air fry at 375°F (190°C) for 14–18 min, flipping halfway, until 165°F (74°C) internal.","Meanwhile make the cream sauce on the stovetop with the remaining spice mix, then spoon it over the air-fried chicken and garnish with green onions."],"fam-taco-casserole":["Brown the seasoned ground beef with onion and green chiles on the stovetop, then layer the browned tortilla halves, beef, black beans, salsa, corn, and cheddar in an air-fryer-safe dish.","Air fry at 350°F (175°C) for 14–18 min, until bubbly and the cheese is golden; rest a few minutes before serving."],"fam-greek-chicken-orzo":["Season and air fry the chicken thighs at 380°F (190°C) for 14–18 min, flipping halfway, until 165°F (74°C) internal.","Meanwhile cook the orzo with the onion, garlic, tomatoes, broth, and spices on the stovetop; serve the air-fried chicken and seared peppers over the orzo, garnished with parsley and feta."],"fam-sun-dried-tomato-chicken":["Season the chicken cutlets with Italian seasoning and salt, oil lightly, and air fry at 375°F (190°C) for 10–14 min, flipping halfway, until 165°F (74°C) internal.","Meanwhile make the sun-dried tomato cream sauce with spinach and olives on the stovetop, then add the sliced air-fried chicken to the sauce to serve."],"fam-one-pot-italian-pasta-chicken":["Toss the bite-sized chicken pieces with a little oil, Italian seasoning, and salt, then air fry at 400°F (200°C) for 8–11 min, shaking once, until 165°F (74°C) internal.","Cook the linguine with the broth, wine, tomatoes, onion, and garlic on the stovetop, then stir in the air-fried chicken, spinach, and Parmesan to serve."],"fam-oven-roasted-potatoes":["Toss the cubed potatoes with olive oil, garlic powder, herbs, paprika, salt, and pepper, then air fry at 400°F (200°C) for 18–22 min, shaking two or three times, until browned and fork-tender."],"kandy-mon-lunch":["Air fry seasoned chicken (oiled) at 375°F (190°C) for 12–16 min, flipping halfway, until 165°F (74°C); slice for the bowls.","Cook the rice separately on the stovetop, then top with the chicken, cucumber, carrot, oil, and lemon."],"kandy-tue-dinner":["Spread the seasoned ground beef (with cumin) in an air-fryer-safe dish or foil tray and air fry at 400°F (200°C) for 8–12 min, stirring and breaking it up twice, until browned and 160°F (71°C).","Stir in the ground flaxseed off the heat, then build bowls with separately cooked rice, corn, tomatoes, lettuce, and feta."],"kandy-wed-lunch":["Toss the pressed, cubed tofu with the garlic-infused oil and air fry at 400°F (200°C) for 12–15 min, shaking once or twice, until golden and crisp.","Cool slightly, then toss with the cucumber, tomatoes, bell pepper, oil, lemon, and feta over the lettuce."],"kandy-wed-dinner":["Toss the sliced chicken with oil, salt, and pepper and air fry at 380°F (193°C) for 8–11 min, shaking once, until 165°F (74°C).","Add the carrot matchsticks and bok choy for the last 4–5 min to char slightly.","Cook the rice noodles separately, then toss everything with ginger, soy sauce, spinach, and scallion greens."],"diet-mon-breakfast":["Air fry the bacon at 350°F (177°C) for 7–10 min, until crispy to your liking.","Scramble the eggs in butter on the stovetop and serve with the bacon and rice cakes."],"diet-mon-lunch":["Air fry seasoned chicken (oiled) at 375°F (190°C) for 12–16 min, flipping halfway, until 165°F (74°C); slice or shred.","Cook the rice separately, then top with chicken, cucumber, carrot, oil, and lemon."],"diet-mon-dinner":["Air fry the cubed peeled potato (1.5 tbsp oil, salt, pepper) at 400°F (200°C) for 10 min, shaking once.","Add the trimmed green beans tossed with oil on top and cook 5 min more.","Add the salmon (oiled, lemon slices on top) and cook 7–9 min, until it flakes and reaches 145°F (63°C)."],"diet-tue-dinner":["Spread the seasoned ground beef (with cumin) in an air-fryer-safe dish and air fry at 400°F (200°C) for 8–12 min, stirring twice, until 160°F (71°C); add the diced bell pepper for the last 4 min.","Build bowls with separately cooked rice, the beef and pepper, corn, and shredded lettuce."],"diet-wed-lunch":["Air fry seasoned chicken (oiled) at 375°F (190°C) for 12–16 min, flipping halfway, until 165°F (74°C); slice or shred.","Cook the quinoa separately, then top with chicken, cucumber, carrot, oil, and lemon."],"diet-wed-dinner":["Toss the sliced chicken with oil, salt, and pepper and air fry at 380°F (193°C) for 8–11 min, shaking once, until 165°F (74°C).","Add the peeled carrot matchsticks and bok choy for the last 4–5 min.","Cook the rice noodles separately, then toss with ginger, soy sauce, and scallion greens."],"diet-thu-dinner":["Air fry the cubed peeled potato (oiled, salted) at 400°F (200°C) for 12–15 min, shaking once, then mash with LF milk, butter, salt, and pepper.","Air fry the pork chops (oiled, seasoned) at 400°F (200°C) for 10–14 min, flipping halfway, until 145°F (63°C); rest 3 min.","Air fry the peeled zucchini slices (buttered or oiled) at 400°F (200°C) for 6–8 min, shaking once, until golden."],"diet-fri-dinner":["Air fry the sliced bell pepper and peeled zucchini (2 tbsp oil) at 400°F (200°C) for 8–10 min, shaking once.","Add the shrimp (oiled, seasoned) and cook 5–7 min, shaking once, until pink and opaque.","Cook the quinoa separately, squeeze lemon over everything, and serve over the quinoa."],"diet-sat-breakfast":["Air fry the bacon at 350°F (177°C) for 7–10 min, until crispy; add the sliced bell pepper for the last 4 min to soften.","Scramble the eggs in butter on the stovetop, warm the corn tortillas, and fill with eggs, bacon, pepper, lettuce, and cheddar."],"diet-sat-lunch":["Air fry seasoned chicken (oiled) at 375°F (190°C) for 12–16 min, flipping halfway, until 165°F (74°C); slice or shred.","Cook the rice separately, then top with chicken, carrot, cucumber, oil, and lemon."],"diet-sat-dinner":["Air fry the cubed peeled sweet potato (1 tbsp oil, salt, pepper) at 400°F (200°C) for 10 min, shaking once.","Add the chicken thighs (oiled, seasoned, lemon on top) and cook 18–22 min, flipping the thighs once, until 175°F (79°C).","Add the green beans tossed with oil for the last 6–8 min."],"diet-sun-breakfast":["Soak the GF bread in the egg/almond milk/vanilla mixture 10–15 sec per side.","Air fry the French toast (buttered basket or parchment) at 350°F (177°C) for 8–10 min, flipping halfway, until golden.","Serve topped with strawberries and maple syrup."],"diet-sun-dinner":["Air fry the peeled potato wedges and carrot sticks (2 tbsp oil, salt, pepper) at 400°F (200°C) for 18–22 min, shaking twice, until golden.","Air fry the steaks at 400°F (200°C) for 8–12 min, flipping halfway, until 130–135°F (54–57°C) for medium-rare; baste with butter and rest 5 min."],"diet-chicken-1":["Air fry the peeled carrot sticks (1.5 tbsp oil, salt, pepper) at 400°F (200°C) for 8 min, shaking once.","Add the chicken breasts (oiled, seasoned, lemon slices on top) and cook 14–18 min, flipping once, until 165°F (74°C).","Cook the rice separately and serve the chicken and carrots over it."],"diet-chicken-2":["Toss the cubed chicken with oil, salt, and pepper and air fry at 380°F (193°C) for 10–14 min, shaking halfway, until 165°F (74°C).","Add the peeled zucchini and sliced bell pepper for the last 6 min, shaking once.","Cook the quinoa separately, squeeze lemon over, and serve over the quinoa."],"diet-chicken-3":["Air fry the peeled potato cubes (1.5 tbsp oil, paprika, salt, pepper) at 400°F (200°C) for 10 min, shaking once.","Add the drumsticks (oiled, paprika, seasoned) and cook 20–25 min, flipping once, until 175°F (79°C).","Add the green beans tossed with oil for the last 7–8 min."],"diet-fish-1":["Air fry the tilapia (patted dry, buttered or oiled, seasoned with lemon, salt, pepper) at 380°F (193°C) for 8–11 min, until it flakes and reaches 145°F (63°C).","Air fry the green beans (lightly oiled) at 400°F (200°C) for 6–8 min, shaking once.","Boil and mash the peeled potatoes with LF milk and butter on the stovetop."],"diet-fish-2":["Air fry the peeled carrot sticks (1.5 tbsp oil, salt, pepper) at 400°F (200°C) for 10 min, shaking once.","Add the cod (oiled, lemon slices on top) and cook 8–11 min, until it flakes and reaches 145°F (63°C).","Cook the rice separately and serve the cod and carrots over it."],"diet-fish-3":["Brush the salmon with the maple-lemon mixture and season; air fry at 390°F (199°C) for 7–9 min, until glazed and 145°F (63°C).","Air fry the peeled zucchini slices (oiled, seasoned) at 400°F (200°C) for 6–8 min, shaking once.","Cook the rice separately and serve the salmon and zucchini over it."],"diet-turkey-1":["Toss the diced bell pepper and grated carrot with olive oil, cumin, salt, and pepper; air fry at 380°F (193°C) for 8–10 min, shaking once.","Form the seasoned ground turkey into a loose patty or small clumps, oil lightly, and air fry at 375°F (190°C) for 10–12 min, breaking and turning once, until 165°F (74°C). Serve over rice cooked separately on the stovetop."],"diet-turkey-2":["Mix the turkey with egg, breadcrumbs, salt, and pepper; roll into 12 meatballs and air fry at 380°F (193°C) for 11–14 min, shaking halfway, until 165°F (74°C).","Add the trimmed green beans (oiled, seasoned) to the basket for the last 6–7 min, shaking once. Prepare the mashed potato separately on the stovetop."],"diet-turkey-3":["Toss the peeled potato, zucchini, and bell pepper with oil, paprika, salt, and pepper; air fry at 400°F (200°C) for 12 min, shaking once.","Oil the turkey cutlets and lay them on top of the veggies; air fry 10–12 min more until the turkey reaches 165°F (74°C) and veggies are golden."],"diet-beef-1":["Toss the carrot matchsticks and sliced bell pepper with a little oil and air fry at 380°F (193°C) for 7–9 min, shaking once.","Add the thinly sliced beef (lightly oiled) and air fry at 400°F (200°C) for 5–7 min, shaking once, until just cooked. Toss with soy sauce, the stovetop-cooked rice noodles, and scallion greens."],"diet-beef-2":["Form the ground beef into a loose patty or clumps, oil lightly, and air fry at 375°F (190°C) for 10–12 min, breaking and turning once, until 160°F (71°C); season with soy sauce, salt, and pepper.","Build bowls with rice cooked separately, the beef, peeled cucumber, and diced bell pepper."],"diet-beef-3":["Toss the peeled potato cubes with oil, salt, and pepper; air fry at 400°F (200°C) for 18–22 min, shaking twice, until golden.","Add the peeled zucchini slices (oiled) for the last 8 min, shaking once.","Pat the steaks dry, rub with oil, and air fry at 400°F (200°C) for 8–12 min, flipping once, to 130–135°F (54–57°C) for medium-rare; rest 3 min before serving."],"chicken-lettuce-wraps":["Form the seasoned ground chicken into a loose patty or clumps, drizzle with garlic-infused oil, and air fry at 375°F (190°C) for 10–12 min, breaking and turning once, until 165°F (74°C).","Add the finely diced carrot and bell pepper for the last 5 min, shaking once. Toss with ginger, soy sauce, and sesame oil, then spoon into lettuce cups with scallion greens, sesame seeds, and lime."],"blt-gf":["Lay the bacon in a single layer in the basket and air fry at 380°F (193°C) for 8–10 min, flipping once, until crispy; drain on paper towel.","Build the BLT on toasted GF bread with mayo, lettuce, tomato, and the air-fried bacon."],"beef-bok-choy-stir-fry":["Toss the julienned carrot with a little garlic-infused oil and air fry at 380°F (193°C) for 6–8 min, shaking once.","Add the beef strips (lightly oiled) and air fry at 400°F (200°C) for 5–7 min, shaking once, until seared. Toss the bok choy in for the last 2–3 min, then finish on the stovetop with the soy-oyster-ginger sauce and cornstarch slurry. Serve over rice."],"shrimp-pad-thai":["Pat the peeled shrimp dry, toss with a little garlic-infused oil, and air fry at 400°F (200°C) for 6–8 min, shaking once, until pink and opaque.","Toss the air-fried shrimp through the soaked noodles, scrambled egg, carrots, bean sprouts, and pad thai sauce finished on the stovetop; top with peanuts, scallion greens, and lime."],"one-pan-chicken-rice":["Rub the bone-in chicken thighs with the garlic-infused oil, lemon zest, half the lemon juice, thyme, paprika, salt, and pepper.","Air fry skin-side up at 380°F (193°C) for 22–26 min, until skin is golden and the chicken reaches 175°F (79°C). Cook the rice separately on the stovetop, then garnish with scallion greens."],"prawn-coconut-curry":["Pat the peeled prawns dry, toss with a little garlic-infused oil, and air fry at 400°F (200°C) for 6–8 min, shaking once, until pink and opaque.","Stir the air-fried prawns into the coconut-curry sauce (with carrot, bok choy, spinach) simmered on the stovetop; serve over rice with scallion greens."],"fodmap-caesar-salad":["Air fry the chicken breast (oiled, seasoned) at 380°F (193°C) for 14–18 min, flipping once, until 165°F (74°C); rest, then slice.","Air fry the cubed GF bread tossed in garlic-infused oil at 360°F (182°C) for 5–7 min, shaking once, until golden and crisp.","Toss romaine with the Caesar dressing and top with the chicken, croutons, and shaved parmesan."],"rice-crepes":["Note: thin crepes don't air-fry well; cook the rice-flour crepes in a pan as written, but use the air fryer for the fruit if you like a warm topping.","Air fry the sliced strawberries at 350°F (175°C) for 4–6 min until softened and jammy, shaking once.","Spoon the warm strawberries over the crepes and drizzle with maple syrup."],"beef-potato-pie":["Air fry the quartered potatoes (skin on) at 400°F (200°C) for 18–22 min, shaking once, until fork-tender; mash with butter and warm milk.","Brown the seasoned ground beef with carrots, zucchini, green beans, tomato paste, flaxseed, stock, tamari and thyme on the stovetop until thickened, then spoon into an air-fryer-safe dish and top with the mash.","Air fry the assembled pie at 360°F (180°C) for 12–15 min until the potato top is golden."],"tuna-nicoise-salad":["Air fry the halved baby potatoes (oiled, seasoned) at 400°F (200°C) for 12–15 min, shaking once, until golden and tender.","Add the trimmed green beans on top and cook 5 min more until tender-crisp.","Boil the eggs separately, then assemble with the leaves, tomatoes, tuna, olives and dressing."],"ginger-pork-rice":["Toss the thinly sliced pork with the ginger-tamari-mirin-maple sauce and a little garlic-infused oil; air fry at 380°F (195°C) for 8–10 min, shaking halfway, until glazed and cooked through (145°F / 63°C).","Cook the brown or white rice separately on the stovetop.","Serve the pork over rice with shredded cabbage, spring onion tops and sesame seeds."],"beef-pepper-stir-fry":["Air fry the sliced peppers and green beans (lightly oiled) at 400°F (200°C) for 8–10 min, shaking once, until tender-crisp.","Add the thinly sliced beef and air fry 4–6 min more, shaking once, until just cooked.","Toss with the warmed tamari-vinegar-ginger-cornstarch sauce on the stovetop until glossy; cook the rice separately and serve."],"steak-chimichurri":["Air fry the potato wedges (skin on, oiled, seasoned) at 400°F (200°C) for 18–22 min, shaking twice, until golden and crisp.","Rub the steaks with garlic-infused oil, salt and pepper; air fry at 400°F (200°C) for 8–12 min, flipping once, to 130–135°F (54–57°C) for medium-rare, then rest 5 min.","Slice the steak, spoon over the chimichurri and serve with the wedges."],"chicken-quesadilla":["Assemble the quesadilla with seasoned shredded chicken, cheese, bell pepper and spring onion tops between corn tortillas; lightly brush the outside with garlic-infused oil.","Air fry at 360°F (180°C) for 6–8 min, flipping halfway, until golden and the cheese melts.","Cut into wedges and serve with the diced tomato salad."],"baked-ziti":["Cook the GF pasta and tomato sauce on the stovetop, toss with ricotta, then layer into an air-fryer-safe dish with mozzarella and parmesan.","Air fry at 360°F (180°C) for 12–16 min until bubbling and golden on top.","Scatter with fresh basil before serving."],"roast-pork-loin":["Air fry the halved potatoes and carrot batons (oiled, seasoned) at 400°F (200°C) for 18–22 min, shaking once, until tender; set aside.","Rub the pork loin with garlic-infused oil, rosemary, thyme, paprika, salt and pepper; air fry at 360°F (180°C) for 22–30 min, turning once, until 145°F (63°C), then rest 10 min.","Slice and serve with the roasted vegetables."],"hf-quinoa-tofu-bowl":["Press and cube the tofu, toss with tamari and a little garlic-infused oil; air fry at 400°F (200°C) for 12–15 min, shaking twice, until golden and crisp.","Add the chopped kale for the last 2–3 min to wilt and crisp slightly.","Cook the quinoa separately; assemble bowls with carrot, edamame, tahini dressing and pumpkin seeds."],"hf-tofu-spinach-curry":["Press and cube the tofu, toss with a little garlic-infused oil; air fry at 400°F (200°C) for 12–15 min, shaking twice, until golden on all sides.","Make the curry sauce with ginger, spices, tomatoes, coconut milk and zucchini on the stovetop, then stir in the air-fried tofu and wilt the spinach.","Cook the rice separately and serve the curry over it."],"hf-chicken-buddha-bowl":["Air fry the carrot batons, zucchini, bell pepper and green beans (oiled, paprika, salt, pepper) at 400°F (200°C) for 14–18 min, shaking twice, until tender.","Rub the chicken breasts with oil, salt and pepper; air fry at 380°F (195°C) for 16–20 min, flipping once, until 165°F (74°C), then rest and slice.","Cook the quinoa separately; assemble bowls with spinach, roasted veg, chicken, lemon and pumpkin seeds."],"greek-chicken-bowl":["Toss the bite-size chicken with garlic-infused oil, oregano, paprika, half the lemon juice, salt and pepper; air fry at 400°F (200°C) for 10–12 min, shaking twice, until golden and 165°F (74°C).","Cook the white rice separately on the stovetop.","Build bowls with rice, chicken, tomatoes, cucumber, feta, olives, parsley, lemon zest and the remaining lemon juice."]});
